-- Rebuild Medina Book 4 lesson 9 strictly from the supplied Arabic sharh.
-- Canonical PDF pages: 36-41. DOC text was used only for extraction and checked against the PDF.
begin;

do $migration$
declare
  existing_count integer;
begin
  select count(*) into existing_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '9';
  if existing_count not in (10, 11) then
    raise exception 'Expected 10 legacy or 11 rebuilt Book 4 lesson 9 rules, found %', existing_count;
  end if;
end $migration$;

-- The legacy lesson merged two independent sharh topics into one card. Preserve all
-- existing IDs and create exactly one new rule row at sort order 11.
insert into public.rules (
  course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar
)
select
  'Мединский курс (Том 4)', '9', '__book4_lesson9_munada__', '', 11, 'rule', '', null
where not exists (
  select 1
  from public.rules
  where course_name = 'Мединский курс (Том 4)'
    and lesson_number = '9'
    and sort_order = 11
);

with incoming(sort_order, title, content, summary, rule_ar) as (
  values
    (1, 'الْأَفْعَالُ الرُّبَاعِيَّةُ الْمُجَرَّدَةُ وَالْمَزِيدَةُ (простые и производные четырёхбуквенные глаголы)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">الْفِعْلُ الرُّبَاعِيُّ الْمُجَرَّدُ لَهُ بَابٌ وَاحِدٌ هُوَ بَابُ فَعْلَلَ، وَمَصْدَرُهُ عَلَى وَزْنِ فِعْلَالٍ أَوْ فَعْلَلَةٍ. وَالْفِعْلُ الرُّبَاعِيُّ الْمَزِيدُ نَوْعَانِ: مَزِيدٌ بِحَرْفٍ وَاحِدٍ، وَمَزِيدٌ بِحَرْفَيْنِ.</span><p class="rule-study-text">Простой четырёхбуквенный глагол имеет одну модель فَعْلَلَ и два типа масдара. Производный четырёхбуквенный глагол получает одну либо две добавочные буквы.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ فَعْلَلَ</span><span class="rule-term-ru">единственная модель простого четырёхбуквенного глагола</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">فِعْلَالٌ وَفَعْلَلَةٌ</span><span class="rule-term-ru">две модели масдара</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">مَزِيدٌ بِحَرْفٍ وَاحِدٍ</span><span class="rule-term-ru">производный глагол с одной добавочной буквой</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">مَزِيدٌ بِحَرْفَيْنِ</span><span class="rule-term-ru">производный глагол с двумя добавочными буквами</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры بَابُ فَعْلَلَ</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">دَحْرَجَ</span><span class="rule-example-ru">покатил</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">بَعْثَرَ</span><span class="rule-example-ru">разбросал</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">زَلْزَلَ</span><span class="rule-example-ru">потряс</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">وَسْوَسَ</span><span class="rule-example-ru">нашёптывал, внушал</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Два масдара</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">زَلْزَلَ ← زِلْزَالٌ وَزَلْزَلَةٌ</span><span class="rule-example-ru">потряс → землетрясение, потрясение</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Производные формы шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمَاضِي</span><span class="rule-table-ru">прошедшее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمُضَارِعُ</span><span class="rule-table-ru">настояще-будущее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْرُ</span><span class="rule-table-ru">повелительное</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-table-ru">действующее причастие</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-table-ru">страдательное причастие</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَعْثَرَ</span><span class="rule-table-ru">разбросал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُبَعْثِرُ</span><span class="rule-table-ru">разбрасывает</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَعْثِرْ</span><span class="rule-table-ru">разбросай</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَعْثَرَةٌ</span><span class="rule-table-ru">разбрасывание</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبَعْثِرٌ</span><span class="rule-table-ru">разбрасывающий</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُبَعْثَرٌ</span><span class="rule-table-ru">разбросанный</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَسْوَسَ</span><span class="rule-table-ru">нашёптывал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُوَسْوِسُ</span><span class="rule-table-ru">нашёптывает</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَسْوِسْ</span><span class="rule-table-ru">нашёптывай</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَسْوَسَةٌ وَوِسْوَاسٌ</span><span class="rule-table-ru">нашёптывание, наущение</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُوَسْوِسٌ</span><span class="rule-table-ru">нашёптывающий</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لَازِمٌ</span><span class="rule-table-ru">глагол непереходный; форма не приводится</span></td></tr></tbody></table></div></div></div>', 'Простой четырёхбуквенный глагол имеет одну модель فَعْلَلَ и два типа масдара. Производный четырёхбуквенный глагол получает одну либо две добавочные буквы.', 'الْفِعْلُ الرُّبَاعِيُّ الْمُجَرَّدُ لَهُ بَابٌ وَاحِدٌ هُوَ بَابُ فَعْلَلَ، وَمَصْدَرُهُ عَلَى وَزْنِ فِعْلَالٍ أَوْ فَعْلَلَةٍ. وَالْفِعْلُ الرُّبَاعِيُّ الْمَزِيدُ نَوْعَانِ: مَزِيدٌ بِحَرْفٍ وَاحِدٍ، وَمَزِيدٌ بِحَرْفَيْنِ.'),
    (2, 'بَابُ تَفَعْلَلَ (порода تَفَعْلَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ تَفَعْلَلَ مَزِيدٌ بِالتَّاءِ فِي أَوَّلِهِ، وَمَصْدَرُهُ عَلَى وَزْنِ تَفَعْلُلٍ، وَمَعْنَاهُ الْمُطَاوَعَةُ، وَلَا يَكُونُ إِلَّا لَازِمًا.</span><p class="rule-study-text">В начале تَفَعْلَلَ добавлена ت. Масдар образуется по модели تَفَعْلُلٌ; порода выражает принятие результата действия и бывает только непереходной.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">حَرْفُ الزِّيَادَةِ: التَّاءُ فِي أَوَّلِهِ</span><span class="rule-term-ru">добавочная ت в начале</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ: تَفَعْلُلٌ</span><span class="rule-term-ru">масдар с даммой перед последней коренной</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">الْمُطَاوَعَةُ</span><span class="rule-term-ru">принятие результата действия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">لَازِمٌ</span><span class="rule-term-ru">порода бывает только непереходной</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Все исходные примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">تَدَحْرَجَ، تَبَعْثَرَ، تَزَلْزَلَ، تَوَسْوَسَ</span><span class="rule-example-ru">покатился; рассыпался; затрясся; подвергся наущению</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">تَدَحْرَجَ ← تَدَحْرُجٌ</span><span class="rule-example-ru">покатился → качение</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">دَحْرَجْتُ الْكُرَةَ، فَتَدَحْرَجَتِ الْكُرَةُ.</span><span class="rule-example-ru">Я покатил мяч, и мяч покатился.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Производные формы шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمَاضِي</span><span class="rule-table-ru">прошедшее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمُضَارِعُ</span><span class="rule-table-ru">настояще-будущее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْرُ</span><span class="rule-table-ru">повелительное</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-table-ru">действующее причастие</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَبَعْثَرَ</span><span class="rule-table-ru">рассыпался</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَتَبَعْثَرُ</span><span class="rule-table-ru">рассыпается</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَبَعْثَرْ</span><span class="rule-table-ru">рассыпься</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَبَعْثُرٌ</span><span class="rule-table-ru">рассыпание</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُتَبَعْثِرٌ</span><span class="rule-table-ru">рассыпающийся</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَزَلْزَلَ</span><span class="rule-table-ru">затрясся</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَتَزَلْزَلُ</span><span class="rule-table-ru">трясётся</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَزَلْزَلْ</span><span class="rule-table-ru">тряси́сь</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَزَلْزُلٌ</span><span class="rule-table-ru">сотрясение</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُتَزَلْزِلٌ</span><span class="rule-table-ru">сотрясающийся</span></td></tr></tbody></table></div></div></div>', 'В начале تَفَعْلَلَ добавлена ت. Масдар образуется по модели تَفَعْلُلٌ; порода выражает принятие результата действия и бывает только непереходной.', 'بَابُ تَفَعْلَلَ مَزِيدٌ بِالتَّاءِ فِي أَوَّلِهِ، وَمَصْدَرُهُ عَلَى وَزْنِ تَفَعْلُلٍ، وَمَعْنَاهُ الْمُطَاوَعَةُ، وَلَا يَكُونُ إِلَّا لَازِمًا.'),
    (3, 'بَابُ اِفْعَنْلَلَ (порода اِفْعَنْلَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ اِفْعَنْلَلَ مَزِيدٌ بِهَمْزَةِ الْوَصْلِ وَالنُّونِ، وَمَصْدَرُهُ عَلَى وَزْنِ اِفْعِنْلَالٍ، وَمَعْنَاهُ الْمُطَاوَعَةُ، وَلَا يَكُونُ إِلَّا لَازِمًا.</span><p class="rule-study-text">Порода اِفْعَنْلَلَ содержит соединительную хамзу и ن, выражает принятие результата действия и бывает только непереходной.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">حَرْفَا الزِّيَادَةِ: هَمْزَةُ الْوَصْلِ وَالنُّونُ</span><span class="rule-term-ru">добавочные соединительная хамза и ن</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ: اِفْعِنْلَالٌ</span><span class="rule-term-ru">масдар с касрой на третьей букве и алиф перед последней</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">الْمُطَاوَعَةُ</span><span class="rule-term-ru">принятие результата действия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">لَازِمٌ</span><span class="rule-term-ru">порода бывает только непереходной</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Исходные примеры и масдар</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِحْرَنْجَمَ</span><span class="rule-example-ru">сгрудился</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِفْرَنْقَعَ</span><span class="rule-example-ru">затрещал, хрустнул</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِقْعَنْسَسَ</span><span class="rule-example-ru">отступил назад</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">اِفْرَنْقَعَ ← اِفْرِنْقَاعٌ</span><span class="rule-example-ru">затрещал → треск, хруст</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">الْمُطَاوَعَةُ — два примера</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">فَرْقَعْتُ الْأَصَابِعَ، فَافْرَنْقَعَتِ الْأَصَابِعُ.</span><span class="rule-example-ru">Я хрустнул пальцами, и пальцы хрустнули.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">حَرْجَمْتُ الْإِبِلَ، فَاحْرَنْجَمَتِ الْإِبِلُ.</span><span class="rule-example-ru">Я собрал верблюдов в тесную группу, и верблюды сгрудились.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Производные формы шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمَاضِي</span><span class="rule-table-ru">прошедшее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمُضَارِعُ</span><span class="rule-table-ru">настояще-будущее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْرُ</span><span class="rule-table-ru">повелительное</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-table-ru">действующее причастие</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِحْرَنْجَمَ</span><span class="rule-table-ru">сгрудился</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَحْرَنْجِمُ</span><span class="rule-table-ru">сгружается</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِحْرَنْجِمْ</span><span class="rule-table-ru">сгрудись</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِحْرِنْجَامٌ</span><span class="rule-table-ru">сгруживание</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُحْرَنْجِمٌ</span><span class="rule-table-ru">сгружающийся</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِفْرَنْقَعَ</span><span class="rule-table-ru">затрещал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَفْرَنْقِعُ</span><span class="rule-table-ru">трещит</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِفْرَنْقِعْ</span><span class="rule-table-ru">хрустни</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِفْرِنْقَاعٌ</span><span class="rule-table-ru">треск, хруст</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُفْرَنْقِعٌ</span><span class="rule-table-ru">трещащий</span></td></tr></tbody></table></div></div></div>', 'Порода اِفْعَنْلَلَ содержит соединительную хамзу и ن, выражает принятие результата действия и бывает только непереходной.', 'بَابُ اِفْعَنْلَلَ مَزِيدٌ بِهَمْزَةِ الْوَصْلِ وَالنُّونِ، وَمَصْدَرُهُ عَلَى وَزْنِ اِفْعِنْلَالٍ، وَمَعْنَاهُ الْمُطَاوَعَةُ، وَلَا يَكُونُ إِلَّا لَازِمًا.'),
    (4, 'بَابُ اِفْعَلَلَّ (порода اِفْعَلَلَّ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ اِفْعَلَلَّ مَزِيدٌ بِهَمْزَةِ الْوَصْلِ وَالتَّضْعِيفِ، وَمَصْدَرُهُ عَلَى وَزْنِ اِفْعِلْلَالٍ، وَمَعْنَاهُ الْمُبَالَغَةُ، وَلَا يَكُونُ إِلَّا لَازِمًا.</span><p class="rule-study-text">Порода اِفْعَلَلَّ содержит соединительную хамзу и удвоение, выражает усиление признака и бывает только непереходной.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">حَرْفَا الزِّيَادَةِ: هَمْزَةُ الْوَصْلِ وَالتَّضْعِيفُ</span><span class="rule-term-ru">добавочные соединительная хамза и удвоение</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ: اِفْعِلْلَالٌ</span><span class="rule-term-ru">масдар по модели اِفْعِلْلَالٌ</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">الْمُبَالَغَةُ</span><span class="rule-term-ru">усиленное проявление признака</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">لَازِمٌ</span><span class="rule-term-ru">порода бывает только непереходной</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِطْمَأَنَّ</span><span class="rule-example-ru">успокоился</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِقْشَعَرَّ</span><span class="rule-example-ru">содрогнулся, покрылся мурашками</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِشْمَأَزَّ</span><span class="rule-example-ru">испытал сильное отвращение</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">اِشْمَأَزَّ ← اِشْمِئْزَازٌ</span><span class="rule-example-ru">испытал отвращение → отвращение</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Производные формы шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمَاضِي</span><span class="rule-table-ru">прошедшее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمُضَارِعُ</span><span class="rule-table-ru">настояще-будущее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْرُ</span><span class="rule-table-ru">повелительное</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-table-ru">действующее причастие</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِطْمَأَنَّ</span><span class="rule-table-ru">успокоился</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَطْمَئِنُّ</span><span class="rule-table-ru">успокаивается</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِطْمَئِنَّ</span><span class="rule-table-ru">успокойся</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِطْمِئْنَانٌ</span><span class="rule-table-ru">спокойствие</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُطْمَئِنٌّ</span><span class="rule-table-ru">спокойный</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِقْشَعَرَّ</span><span class="rule-table-ru">содрогнулся</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَقْشَعِرُّ</span><span class="rule-table-ru">содрогается</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِقْشَعِرَّ</span><span class="rule-table-ru">содрогнись</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِقْشِعْرَارٌ</span><span class="rule-table-ru">содрогание</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُقْشَعِرٌّ</span><span class="rule-table-ru">содрогающийся</span></td></tr></tbody></table></div></div></div>', 'Порода اِفْعَلَلَّ содержит соединительную хамзу и удвоение, выражает усиление признака и бывает только непереходной.', 'بَابُ اِفْعَلَلَّ مَزِيدٌ بِهَمْزَةِ الْوَصْلِ وَالتَّضْعِيفِ، وَمَصْدَرُهُ عَلَى وَزْنِ اِفْعِلْلَالٍ، وَمَعْنَاهُ الْمُبَالَغَةُ، وَلَا يَكُونُ إِلَّا لَازِمًا.'),
    (5, 'ضَمِيرُ الْفَصْلِ (разделительное местоимение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-subject" dir="rtl" lang="ar">ضَمِيرُ الْفَصْلِ ضَمِيرُ رَفْعٍ مُنْفَصِلٌ يُؤْتَى بِهِ لِلْفَصْلِ بَيْنَ الْخَبَرِ وَالتَّابِعِ. يَجِبُ أَنْ يُطَابِقَ مَا قَبْلَهُ، وَأَنْ يَكُونَ مَا قَبْلَهُ وَمَا بَعْدَهُ مَعْرِفَتَيْنِ. يُفِيدُ الْحَصْرَ وَالتَّأْكِيدَ وَإِلْزَامَ مَا بَعْدَهُ أَنْ يَكُونَ خَبَرًا، وَلَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><p class="rule-study-text">ضَمِيرُ الْفَصْلِ отделяет сказуемое от возможного определения или الْبَدَلُ. Оно согласуется с предшествующим именем, стоит между двумя определёнными элементами, усиливает и ограничивает смысл и однозначно делает последующее слово сказуемым.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar ar-tone-subject" dir="rtl" lang="ar">ضَمِيرُ رَفْعٍ مُنْفَصِلٌ</span><span class="rule-term-ru">отдельное местоимение именительного разряда</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">التَّابِعُ: النَّعْتُ وَالْبَدَلُ</span><span class="rule-term-ru">зависимый элемент здесь — определение либо الْبَدَلُ</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ</span><span class="rule-term-ru">не имеет синтаксического места</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Условия</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْطُ</span><span class="rule-table-ru">условие</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русское пояснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَنْ يَكُونَ ضَمِيرَ رَفْعٍ مُنْفَصِلًا</span><span class="rule-table-ru">форма местоимения</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">ضَمِيرُ رَفْعٍ مُنْفَصِلٌ</span><span class="rule-table-ru">должно быть отдельным местоимением именительного разряда</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَنْ يُطَابِقَ مَا قَبْلَهُ</span><span class="rule-table-ru">согласование</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمُطَابَقَةُ فِي الشَّخْصِ وَالْعَدَدِ وَالْجِنْسِ</span><span class="rule-table-ru">согласуется с предшествующим по лицу, числу и роду</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَنْ يَكُونَ مَا قَبْلَهُ وَمَا بَعْدَهُ مَعْرِفَتَيْنِ</span><span class="rule-table-ru">определённость</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">كِلَاهُمَا مَعْرِفَةٌ</span><span class="rule-table-ru">оба окружающих элемента должны быть определёнными</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Три пользы</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْحَصْرُ</span><span class="rule-term-ru">ограничение смысла</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">التَّأْكِيدُ</span><span class="rule-term-ru">усиление</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">إِلْزَامُ أَنْ يَكُونَ مَا بَعْدَهُ خَبَرًا</span><span class="rule-term-ru">обязательное понимание последующего как сказуемого</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">مُحَمَّدٌ هُوَ النَّاجِحُ.</span><span class="rule-example-ru">Мухаммад — именно тот, кто преуспел.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">فَاطِمَةُ هِيَ الْفَائِزَةُ.</span><span class="rule-example-ru">Фатима — именно победительница.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">أُولَئِكَ هُمُ الْفَائِزُونَ.</span><span class="rule-example-ru">Именно те являются победителями.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">أُولَئِكَ هُنَّ الْمُؤْمِنَاتُ.</span><span class="rule-example-ru">Именно те женщины являются верующими.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Почему местоимение устраняет двусмысленность</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعِبَارَةُ</span><span class="rule-table-ru">выражение</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِعْرَابُ النَّاجِحِ</span><span class="rule-table-ru">возможный разбор النَّاجِحُ</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُحَمَّدٌ النَّاجِحُ</span><span class="rule-table-ru">Мухаммад, преуспевший / Мухаммад — преуспевший</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ أَوْ نَعْتٌ</span><span class="rule-table-ru">может быть сказуемым либо определением при ожидаемом далее сказуемом</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُحَمَّدٌ هُوَ النَّاجِحُ</span><span class="rule-table-ru">Мухаммад — именно преуспевший</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ لَا غَيْرُ</span><span class="rule-table-ru">только сказуемое</span></td></tr></tbody></table></div></div></div>', 'ضَمِيرُ الْفَصْلِ отделяет сказуемое от возможного определения или الْبَدَلُ. Оно согласуется с предшествующим именем, стоит между двумя определёнными элементами, усиливает и ограничивает смысл и однозначно делает последующее слово сказуемым.', 'ضَمِيرُ الْفَصْلِ ضَمِيرُ رَفْعٍ مُنْفَصِلٌ يُؤْتَى بِهِ لِلْفَصْلِ بَيْنَ الْخَبَرِ وَالتَّابِعِ. يَجِبُ أَنْ يُطَابِقَ مَا قَبْلَهُ، وَأَنْ يَكُونَ مَا قَبْلَهُ وَمَا بَعْدَهُ مَعْرِفَتَيْنِ. يُفِيدُ الْحَصْرَ وَالتَّأْكِيدَ وَإِلْزَامَ مَا بَعْدَهُ أَنْ يَكُونَ خَبَرًا، وَلَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.'),
    (6, 'إِقَامَةُ إِذَا الْفُجَائِيَّةِ مَقَامَ الْفَاءِ (замена فَاءُ جَوَابِ الشَّرْطِ внезапной إِذَا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">إِذَا كَانَ جَوَابُ الشَّرْطِ جُمْلَةً اسْمِيَّةً وَجَبَ اقْتِرَانُهُ بِالْفَاءِ، وَيَجُوزُ أَنْ تَقُومَ إِذَا الْفُجَائِيَّةُ مَقَامَ الْفَاءِ، بِشَرْطِ أَنْ يَكُونَ الْجَوَابُ جُمْلَةً اسْمِيَّةً وَأَنْ تَكُونَ أَدَاةُ الشَّرْطِ إِنْ أَوْ إِذَا.</span><p class="rule-study-text">Именной ответ условия обычно связывается с условием через فَـ. При условной частице إِنْ либо إِذَا место этой فَـ может занять внезапная إِذَا.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">جَوَابُ الشَّرْطِ جُمْلَةٌ اسْمِيَّةٌ</span><span class="rule-term-ru">ответ условия является именным предложением</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">أَدَاةُ الشَّرْطِ: إِنْ أَوْ إِذَا</span><span class="rule-term-ru">условная частица — إِنْ или إِذَا</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">إِذَا الْفُجَائِيَّةُ مَقَامَ الْفَاءِ</span><span class="rule-term-ru">внезапная إِذَا занимает место связующей فَـ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранические примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿وَإِذَا ذُكِرَ ٱلَّذِينَ مِن دُونِهِۦٓ إِذَا هُمۡ يَسۡتَبۡشِرُونَ﴾</span><span class="rule-example-ru">«А когда поминают тех, кто помимо Него, они вдруг радуются»: условие с إِذَا, именной ответ начинается внезапной إِذَا.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿وَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ إِذَا هُمۡ يَقۡنَطُونَ﴾</span><span class="rule-example-ru">«А если их постигнет беда за то, что совершили их руки, они вдруг отчаиваются»: условие с إِنْ, именной ответ начинается внезапной إِذَا.</span></div></div></div></div>', 'Именной ответ условия обычно связывается с условием через فَـ. При условной частице إِنْ либо إِذَا место этой فَـ может занять внезапная إِذَا.', 'إِذَا كَانَ جَوَابُ الشَّرْطِ جُمْلَةً اسْمِيَّةً وَجَبَ اقْتِرَانُهُ بِالْفَاءِ، وَيَجُوزُ أَنْ تَقُومَ إِذَا الْفُجَائِيَّةُ مَقَامَ الْفَاءِ، بِشَرْطِ أَنْ يَكُونَ الْجَوَابُ جُمْلَةً اسْمِيَّةً وَأَنْ تَكُونَ أَدَاةُ الشَّرْطِ إِنْ أَوْ إِذَا.'),
    (7, 'تَقَدُّمُ هَمْزَةِ الِاسْتِفْهَامِ عَلَى حُرُوفِ الْعَطْفِ (вопросительная хамза перед союзами)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">تَتَقَدَّمُ هَمْزَةُ الِاسْتِفْهَامِ عَلَى حُرُوفِ الْعَطْفِ، أَمَّا أَخَوَاتُهَا مِنْ أَدَوَاتِ الِاسْتِفْهَامِ فَتَتَأَخَّرُ عَنْ حُرُوفِ الْعَطْفِ.</span><p class="rule-study-text">Только вопросительная хамза ставится раньше союза: أَوَ и أَفَ. Другие вопросительные слова стоят после союза: فَهَلْ, وَهَلْ, وَكَيْفَ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Порядок элементов</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَدَاةُ الِاسْتِفْهَامِ</span><span class="rule-table-ru">вопросительное средство</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحُكْمُ</span><span class="rule-table-ru">положение относительно союза</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">هَمْزَةُ الِاسْتِفْهَامِ</span><span class="rule-table-ru">вопросительная хамза</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَتَقَدَّمُ عَلَى حَرْفِ الْعَطْفِ</span><span class="rule-table-ru">ставится перед союзом</span></td><td><span class="rule-table-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿أَوَلَمۡ تُؤۡمِن﴾</span><span class="rule-table-ru">«Разве ты не уверовал?» — أَ стоит перед وَ.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">هَمْزَةُ الِاسْتِفْهَامِ</span><span class="rule-table-ru">вопросительная хамза</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَتَقَدَّمُ عَلَى حَرْفِ الْعَطْفِ</span><span class="rule-table-ru">ставится перед союзом</span></td><td><span class="rule-table-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿أَفَلَا يَنظُرُونَ إِلَى ٱلۡإِبِلِ﴾</span><span class="rule-table-ru">«Разве они не смотрят на верблюдов?» — أَ стоит перед فَ.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَخَوَاتُ الْهَمْزَةِ</span><span class="rule-table-ru">другие вопросительные слова</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَتَأَخَّرُ عَنْ حَرْفِ الْعَطْفِ</span><span class="rule-table-ru">ставятся после союза</span></td><td><span class="rule-table-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿فَهَلۡ يُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلۡفَٰسِقُونَ﴾</span><span class="rule-table-ru">«Разве погибает кто-либо, кроме нечестивого народа?» — هَلْ стоит после فَ.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры шарха с другими вопросительными словами</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">وَهَلْ هَذَا جَائِزٌ؟</span><span class="rule-example-ru">И допустимо ли это?</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">وَكَيْفَ حَصَلَ ذَلِكَ؟</span><span class="rule-example-ru">И как это произошло?</span></div></div></div></div>', 'Только вопросительная хамза ставится раньше союза: أَوَ и أَفَ. Другие вопросительные слова стоят после союза: فَهَلْ, وَهَلْ, وَكَيْفَ.', 'تَتَقَدَّمُ هَمْزَةُ الِاسْتِفْهَامِ عَلَى حُرُوفِ الْعَطْفِ، أَمَّا أَخَوَاتُهَا مِنْ أَدَوَاتِ الِاسْتِفْهَامِ فَتَتَأَخَّرُ عَنْ حُرُوفِ الْعَطْفِ.'),
    (8, 'مَا الْمَصْدَرِيَّةُ الظَّرْفِيَّةُ (масдарно-временная مَا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">مَا الْمَصْدَرِيَّةُ الظَّرْفِيَّةُ هِيَ الَّتِي تُؤَوَّلُ مَعَ مَا بَعْدَهَا بِمَصْدَرٍ صَرِيحٍ مَعَ الدَّلَالَةِ عَلَى الظَّرْفِيَّةِ، أَيْ عَلَى الْمُدَّةِ.</span><p class="rule-study-text">مَا الْمَصْدَرِيَّةُ الظَّرْفِيَّةُ превращает последующую конструкцию в явный масдар и одновременно обозначает продолжительность: «в течение того времени, пока…».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и истолкование длительности</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">исходное выражение и перевод</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">التَّأْوِيلُ</span><span class="rule-table-ru">истолкование</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَطِيعُونِي مَا أَطَعْتُ اللَّهَ فِيكُمْ.</span><span class="rule-table-ru">Повинуйтесь мне, пока я повинуюсь Аллаху в отношении вас.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُدَّةَ إِطَاعَتِي اللَّهَ</span><span class="rule-table-ru">в течение моего повиновения Аллаху</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سَيَبْقَى الْإِسْلَامُ مَا بَقِيَ الْعَالَمُ.</span><span class="rule-table-ru">Ислам будет существовать, пока существует мир.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُدَّةَ بَقَاءِ الْعَالَمِ</span><span class="rule-table-ru">в течение существования мира</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سَأَجْلِسُ عَلَى هَذَا الْكُرْسِيِّ مَا لَمْ يَأْتِ صَاحِبُهُ.</span><span class="rule-table-ru">Я буду сидеть на этом стуле, пока не придёт его владелец.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُدَّةَ عَدَمِ إِتْيَانِ صَاحِبِهِ</span><span class="rule-table-ru">в течение отсутствия прихода его владельца</span></td></tr><tr><td><span class="rule-table-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿وَأَوۡصَٰنِي بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمۡتُ حَيّٗا﴾</span><span class="rule-table-ru">«И заповедал мне молитву и закят, пока я жив».</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُدَّةَ دَوَامِي حَيًّا</span><span class="rule-table-ru">в течение моей жизни</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَابُ: مَا دُمْتُ حَيًّا</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">مَا: حَرْفُ مَصْدَرٍ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-example-ru">مَا — неизменяемая на сукуне масдарная частица без синтаксического места.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">دُمْتُ: فِعْلٌ مَاضٍ نَاقِصٌ مَبْنِيٌّ عَلَى السُّكُونِ لِاتِّصَالِهِ بِالتَّاءِ، وَالتَّاءُ فِي مَحَلِّ رَفْعٍ اسْمُ دَامَ.</span><span class="rule-example-ru">دُمْتُ — неполный прошедший глагол на сукуне из-за присоединения ت; ت занимает именительное место имени دَامَ.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">حَيًّا: خَبَرُ دَامَ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">حَيًّا — сказуемое دَامَ в винительном падеже с явной фатхой.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">الْمَصْدَرُ الْمُؤَوَّلُ «مَا دُمْتُ حَيًّا» فِي مَحَلِّ نَصْبٍ مَفْعُولٌ فِيهِ.</span><span class="rule-example-ru">Вся конструкция مَا دُمْتُ حَيًّا занимает винительное место обстоятельства времени.</span></div></div></div></div>', 'مَا الْمَصْدَرِيَّةُ الظَّرْفِيَّةُ превращает последующую конструкцию в явный масдар и одновременно обозначает продолжительность: «в течение того времени, пока…».', 'مَا الْمَصْدَرِيَّةُ الظَّرْفِيَّةُ هِيَ الَّتِي تُؤَوَّلُ مَعَ مَا بَعْدَهَا بِمَصْدَرٍ صَرِيحٍ مَعَ الدَّلَالَةِ عَلَى الظَّرْفِيَّةِ، أَيْ عَلَى الْمُدَّةِ.'),
    (9, 'جَوَازُ فَكِّ الْإِدْغَامِ فِي الْفِعْلِ الْمُضَعَّفِ (допустимость раскрытия удвоения в удвоенном глаголе)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">يَجُوزُ فَكُّ الْإِدْغَامِ فِي الْفِعْلِ الْمُضَارِعِ الْمُضَعَّفِ الْمَجْزُومِ، وَفِي فِعْلِ الْأَمْرِ مِنْهُ.</span><p class="rule-study-text">В усечённом настояще-будущем и в повелительной форме удвоенного глагола допустимы и слитое удвоение, и раскрытие двух одинаковых коренных.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Две допустимые формы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَوْضِعُ</span><span class="rule-table-ru">положение</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْإِدْغَامُ</span><span class="rule-table-ru">с сохранённым удвоением</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَكُّ الْإِدْغَامِ</span><span class="rule-table-ru">с раскрытием</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">الْمُضَارِعُ الْمَجْزُومُ</span><span class="rule-table-ru">усечённое настояще-будущее</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَمْ يَشُدَّ</span><span class="rule-table-ru">он не затянул, не укрепил</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَمْ يَشْدُدْ</span><span class="rule-table-ru">то же значение с раскрытием двух د</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلُ الْأَمْرِ</span><span class="rule-table-ru">повелительное</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">شُدَّ</span><span class="rule-table-ru">затяни, укрепи</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اُشْدُدْ</span><span class="rule-table-ru">то же значение с раскрытием двух د</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранические примеры раскрытия</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿وَٱحۡلُلۡ عُقۡدَةٗ مِّن لِّسَانِي﴾</span><span class="rule-example-ru">«И развяжи узел на моём языке»: اُحْلُلْ содержит раскрытые ل.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿وَٱغۡضُضۡ مِن صَوۡتِكَ﴾</span><span class="rule-example-ru">«И понизь свой голос»: اُغْضُضْ содержит раскрытые ض.</span></div></div></div></div>', 'В усечённом настояще-будущем и в повелительной форме удвоенного глагола допустимы и слитое удвоение, и раскрытие двух одинаковых коренных.', 'يَجُوزُ فَكُّ الْإِدْغَامِ فِي الْفِعْلِ الْمُضَارِعِ الْمُضَعَّفِ الْمَجْزُومِ، وَفِي فِعْلِ الْأَمْرِ مِنْهُ.'),
    (10, 'مِنْ التَّبْعِيضِيَّةُ (частичная مِنْ — «некоторые, часть из»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-jarr" dir="rtl" lang="ar">مِنْ التَّبْعِيضِيَّةُ حَرْفُ جَرٍّ يَدُلُّ عَلَى أَنَّ الْمَذْكُورَ بَعْدَهَا بَعْضٌ مِنْ كُلٍّ.</span><p class="rule-study-text">Частичная مِنْ обозначает не весь объём, а некоторую часть: مِمَّا رَزَقْنَاهُمْ значит «из того, чем Мы их наделили».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ﴾</span><span class="rule-example-ru">«И расходуют из того, чем Мы их наделили»: مِمَّا رَزَقْنَاهُمْ означает بَعْضَ الَّذِي رَزَقْنَاهُمْ — часть дарованного.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Остальные примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar ar-tone-jarr" dir="rtl" lang="ar">مِنَ الطُّلَّابِ مَنْ يَعْرِفُ الْإِنْكِلِيزِيَّةَ.</span><span class="rule-example-ru">Среди студентов есть те, кто знает английский, то есть некоторые из них.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar ar-tone-jarr" dir="rtl" lang="ar">أَنْتَ مِنْ أَحْسَنِ الطُّلَّابِ أَدَبًا.</span><span class="rule-example-ru">Ты — один из лучших студентов по воспитанности.</span></div></div></div></div>', 'Частичная مِنْ обозначает не весь объём, а некоторую часть: مِمَّا رَزَقْنَاهُمْ значит «из того, чем Мы их наделили».', 'مِنْ التَّبْعِيضِيَّةُ حَرْفُ جَرٍّ يَدُلُّ عَلَى أَنَّ الْمَذْكُورَ بَعْدَهَا بَعْضٌ مِنْ كُلٍّ.'),
    (11, 'الْمُنَادَى الْمُضَافُ إِلَى يَاءِ الْمُتَكَلِّمِ (обращение, присоединённое к يَاءِ الْمُتَكَلِّمِ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-subject" dir="rtl" lang="ar">يَجُوزُ فِي يَاءِ الْمُنَادَى الْمُضَافِ إِلَى يَاءِ الْمُتَكَلِّمِ خَمْسَةُ أَوْجُهٍ: حَذْفُ الْيَاءِ مَعَ بَقَاءِ الْكَسْرَةِ، وَإِثْبَاتُهَا سَاكِنَةً، وَإِثْبَاتُهَا مَفْتُوحَةً، وَقَلْبُهَا أَلِفًا، وَقَلْبُهَا أَلِفًا ثُمَّ حَذْفُ الْأَلِفِ وَالِاسْتِغْنَاءُ عَنْهَا بِالْفَتْحَةِ.</span><p class="rule-study-text">В обращении вида «о мой Господь / о мой народ» шарх приводит пять допустимых способов произнесения и написания окончания يَاءُ الْمُتَكَلِّمِ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Пять допустимых форм</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْوَجْهُ</span><span class="rule-table-ru">способ</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">формы и русский смысл</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُلَاحَظَةٌ</span><span class="rule-table-ru">замечание шарха</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَذْفُ الْيَاءِ مَعَ بَقَاءِ الْكَسْرَةِ</span><span class="rule-table-ru">удалить ي, сохранить касру</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">يَا رَبِّ، وَيَا قَوْمِ</span><span class="rule-table-ru">о мой Господь; о мой народ</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">هَذَا هُوَ الْأَكْثَرُ</span><span class="rule-table-ru">это наиболее частая форма</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِثْبَاتُ الْيَاءِ سَاكِنَةً</span><span class="rule-table-ru">сохранить неподвижную ي</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">يَا رَبِّيْ، وَيَا قَوْمِيْ</span><span class="rule-table-ru">о мой Господь; о мой народ</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">هَذَا أَقَلُّ مِنَ الْأَوَّلِ</span><span class="rule-table-ru">реже первой формы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِثْبَاتُ الْيَاءِ مَفْتُوحَةً</span><span class="rule-table-ru">сохранить ي с фатхой</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">يَا رَبِّيَ، وَيَا قَوْمِيَ</span><span class="rule-table-ru">о мой Господь; о мой народ</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">هَذَا أَقَلُّ مِنَ السَّابِقِ</span><span class="rule-table-ru">реже предыдущей формы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قَلْبُ الْيَاءِ أَلِفًا</span><span class="rule-table-ru">заменить ي на алиф</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">يَا رَبَّا، وَيَا قَوْمَا؛ وَفِي الْوَقْفِ: يَا رَبَّاهْ، وَيَا قَوْمَاهْ</span><span class="rule-table-ru">о мой Господь; о мой народ; при остановке возможна هَاءُ السَّكْتِ</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">تَلْحَقُ هَاءُ السَّكْتِ عِنْدَ الْوَقْفِ</span><span class="rule-table-ru">при остановке может присоединяться هَاءُ السَّكْتِ</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قَلْبُ الْيَاءِ أَلِفًا ثُمَّ حَذْفُ الْأَلِفِ</span><span class="rule-table-ru">заменить ي на алиф, затем удалить алиф</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">يَا رَبَّ، وَيَا قَوْمَ</span><span class="rule-table-ru">о мой Господь; о мой народ</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يُسْتَغْنَى عَنِ الْأَلِفِ بِالْفَتْحَةِ</span><span class="rule-table-ru">вместо алиф остаётся фатха</span></td></tr></tbody></table></div></div></div>', 'В обращении вида «о мой Господь / о мой народ» шарх приводит пять допустимых способов произнесения и написания окончания يَاءُ الْمُتَكَلِّمِ.', 'يَجُوزُ فِي يَاءِ الْمُنَادَى الْمُضَافِ إِلَى يَاءِ الْمُتَكَلِّمِ خَمْسَةُ أَوْجُهٍ: حَذْفُ الْيَاءِ مَعَ بَقَاءِ الْكَسْرَةِ، وَإِثْبَاتُهَا سَاكِنَةً، وَإِثْبَاتُهَا مَفْتُوحَةً، وَقَلْبُهَا أَلِفًا، وَقَلْبُهَا أَلِفًا ثُمَّ حَذْفُ الْأَلِفِ وَالِاسْتِغْنَاءُ عَنْهَا بِالْفَتْحَةِ.')
)
update public.rules as r
set title = incoming.title,
    content = incoming.content,
    rule_kind = 'rule',
    summary = incoming.summary,
    rule_ar = incoming.rule_ar
from incoming
where r.course_name = 'Мединский курс (Том 4)'
  and r.lesson_number = '9'
  and r.sort_order = incoming.sort_order;

delete from public.rule_sources
where rule_id in (
  select id from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '9'
);

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الدَّرْسُ التَّاسِعُ
الأفعالُ الرُّبَاعِيَّةُ الْمُجَرَّدَةُ ، والْمَزِيدَةُ
أَوَّلاً : الفعلُ الرُّبَاعِيُّ المجرَّدُ ، له بابٌ واحدٌ هو : بَـابُ فَعْلَلَ .
من أمثلته : دَحْرَجَ ، بَعْثَرَ ، زَلْزَلَ ، وَسْوَسَ .
مصدره : فِعْلاَلٌ ، وفَعْلَلَةٌ ، نحو : زَلْزَلَ : زِلْزَالٌ ، وزَلْزَلَةٌ .
