insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'ضَمِيرُ الفَصْلِ
ضميرُ رفعٍ مُنفصلٍ ، يُؤْتَى به لِلْفَصْلِ بين ما هو خبرٌ ، وما هو تابعٌ .  : ضميرُ الفصلِ
والمراد بالتَّابع هنا : النَّعْتُ ، والْبَدَلُ .
شروطه :
1- أن يكونَ ضميرَ رفعٍ منفصلاً .                   2- أن يُطابق ما قبله .
ويُشترط في ما قبله ، وما بعده أن يكونا معرفتين .
فائدته :
1- الْحَصْرُ .              2- التَّأكيدُ .              3- إلزامُ أن يكون ما بعده خبراً .
إعرابه : لا محلَّ له من الإعراب .
الأمثلة :
محمدٌ هُوَ النَّاجِحُ . فاطمةُ هِيَ الفائزةُ . أولئكَ هُمُ الفائزون . أولئك هُنَّ المؤمناتُ .
توضيح :
إذا قلت : محمدٌ الناجحُ ، جاز إعراب الناجح خبراً ، وجاز إعرابه نعتاً على اعتبار أنّ الخبرَ آتٍ . فإذا أدخلت ضمير الفصل ، وقلت : محمد هو الناجح ، صار إعراب الناجح خبراً لا غير .', 38, 39, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '9' and sort_order = 5;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'إقامةُ إذا الفجائيَّةِ مَقَامَ الفَاءِ
إذا كان جواب الشرط جملة اسمية وجب اقترانه بالفاء . يجوز إقامة إذا الفجائية مقام
الفاء , كما في قوله تعالى : ﴿ وَإِذَا ذُكِرَ الَّذِينَ مِنْ دُونِهِ إِذَا هُمْ يَسْتَبْشِرُونَ ﴾ .
وقوله تعالى : ﴿ وَإِنْ تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ إِذَا هُمْ يَقْنَطُونَ ﴾ .
* يُشترط أن يكون الجواب جملة اسميّة ، وأن تكون أداة الشرط ( إنْ ، أو إذا ) .', 39, 39, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '9' and sort_order = 6;

