insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'مَا الْمَصْدَرِيَّةُ الظَّرْفِيَّةُ
هي : التي تُؤَوَّلُ بمصدر صريح مع الدَّلالة على الظَّرفيَّة .  ما المصدريَّة الظَّرفيَّة ،
نحو قول أبي بكر رضي الله عنه : " أَطِيعُونِي مَا أَطَعْتُ اللهَ فِيكُمْ " أي : مُدَّةَ إطاعتي اللهَ .
ونحو قولك : سيبقى الإسلامُ ما بَقِيَ الْعَالَمُ ، أي : مدة بقاء العالم .
ونحو : سأجلسُ على هذا الكرسيَّ ما لم يأتِ صاحبُه ، أي : مدة عَدَمِ إِتْيَانِ صاحبِه .
وكما في قوله تعالى : ﴿ وَأَوْصَانِي بِالصَّلَاةِ وَالزَّكَاةِ مَا دُمْتُ حَيًّا ﴾ .
الإعراب : ﴿ مَا دُمْتُ حَيًّا ﴾
ما : حرفُ مصدرٍ مبنيٌّ على السُّكون لا محل له من الإعراب .
دُمْتُ : فعلٌ ماضٍ ناقصٌ مبنيٌّ على السُّكون لاتصاله بالتاء ، والتاء في محل رفع اسم دام .
حيًّا : خبر دام منصوب وعلامة نصبه الفتحة الظاهرة .
والمصدر المؤوَّل ( ما دمت حَيًّا ) في محل نصب مفعول فيه .', 40, 40, 1
from public.rules
